begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000226011','library-a@veyocast.test'),('00000000-0000-4000-8000-000000226012','library-b@veyocast.test');
insert into public.profiles(id,display_name) values ('00000000-0000-4000-8000-000000226011','Library A'),('00000000-0000-4000-8000-000000226012','Library B');
insert into public.tenants(id,name,slug) values ('10000000-0000-4000-8000-000000226011','Library A','library-a'),('10000000-0000-4000-8000-000000226012','Library B','library-b');
insert into public.tenant_memberships(tenant_id,user_id,role) values ('10000000-0000-4000-8000-000000226011','00000000-0000-4000-8000-000000226011','tenant_admin'),('10000000-0000-4000-8000-000000226012','00000000-0000-4000-8000-000000226012','tenant_admin');
insert into public.studio_projects(tenant_id,name,orientation,width,height) select '10000000-0000-4000-8000-000000226011','Library '||lpad(n::text,4,'0'),'landscape',1920,1080 from generate_series(1,1005) n;
insert into public.studio_projects(tenant_id,name,orientation,width,height) values ('10000000-0000-4000-8000-000000226012','Other tenant secret','portrait',1080,1920);
insert into public.media_assets(id,tenant_id,title,kind,original_file_name,mime_type,storage_path,file_size_bytes,width,height) values ('20000000-0000-4000-8000-000000226011','10000000-0000-4000-8000-000000226011','Library image','image','image.png','image/png','tenants/10000000-0000-4000-8000-000000226011/assets/20000000-0000-4000-8000-000000226011/original.png',100,1,1);
set local role anon;
select throws_ok($$select * from public.sync_content_library_v1$$,'42501',null,'anonymous cannot read the unified library');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226011',true);
select is((select count(*)::integer from public.sync_content_library_v1),1006,'one complete count includes media and more than 1000 designs');
select is((select count(*)::integer from public.sync_content_library_v1 where tenant_id='10000000-0000-4000-8000-000000226012'),0,'tenant A cannot read tenant B through the invoker view');
select is((select title from public.sync_content_library_v1 where kind='studio' order by title,content_key limit 1 offset 1000),'Library 1001','pagination reaches beyond the old 1000-row limit');
select is((select count(*)::integer from public.sync_content_library_v1 where kind='media'),1,'media filter agrees with the complete result set');
select is((select count(*)::integer from public.sync_content_library_v1 where title ilike '%1005%'),1,'search reaches the last design');
select throws_ok($$delete from public.sync_content_library_v1$$,'55000',null,'read projection cannot replace guarded domain mutations');
select is(has_table_privilege('authenticated','public.sync_content_library_v1','DELETE'),false,'browser role has no delete grant on the projection');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226012',true);
select is((select count(*)::integer from public.sync_content_library_v1),1,'tenant B only sees its own content');
select is((select title from public.sync_content_library_v1),'Other tenant secret','original resource identity and title remain authoritative');
reset role;
select ok((select 'security_invoker=true'=any(reloptions) from pg_class where oid='public.sync_content_library_v1'::regclass),'view explicitly preserves underlying RLS');
select is((select width from public.sync_content_library_v1 where id='20000000-0000-4000-8000-000000226011'),1,'actual square media width remains one pixel, not an invented canvas');
select is((select orientation from public.sync_content_library_v1 where id='20000000-0000-4000-8000-000000226011'),'square','square media is not mislabeled as 16:9');
-- A library row represents the complete series, not a second row per child.
insert into public.studio_series(id,tenant_id,owner_user_id,name) values('30000000-0000-4000-8000-000000226011','10000000-0000-4000-8000-000000226011','00000000-0000-4000-8000-000000226011','Library series');
insert into public.studio_series_items(tenant_id,series_id,project_id,sort_order) select tenant_id,'30000000-0000-4000-8000-000000226011',id,0 from public.studio_projects where name='Library 0001';
select is((select count(*)::integer from public.sync_content_library_v1 where title='Library 0001'),0,'series child is not duplicated in the unified library');
select is((select status from public.sync_content_library_v1 where title='Library series'),'draft','an unrendered series is not labeled ready');
select ok((select placement is null from public.sync_content_library_v1 where title='Library series'),'an incomplete series cannot be selected as ready playback');

-- Readiness is tied to the current draft hash, never just any historical export.
insert into public.studio_project_drafts(tenant_id,project_id,document_json,document_hash) select tenant_id,id,'{}',encode(digest('{}','sha256'),'hex') from public.studio_projects where name='Library 0001';
insert into public.studio_revisions(id,tenant_id,project_id,revision_number,draft_revision,document_json,document_hash) select '40000000-0000-4000-8000-000000226011',tenant_id,id,1,0,'{}',repeat('c',64) from public.studio_projects where name='Library 0001';
update public.media_assets set status='ready',checksum_sha256=repeat('a',64) where id='20000000-0000-4000-8000-000000226011';
insert into public.studio_render_jobs(id,tenant_id,project_id,revision_id,status,output_kind,request_idempotency_key,request_hash,media_asset_id,progress,finished_at) select '50000000-0000-4000-8000-000000226011',tenant_id,id,'40000000-0000-4000-8000-000000226011','completed','png','50000000-0000-4000-8000-000000226012',repeat('d',64),'20000000-0000-4000-8000-000000226011',100,now() from public.studio_projects where name='Library 0001';
insert into public.studio_exports(tenant_id,project_id,revision_id,render_job_id,media_asset_id,output_kind,width,height,checksum_sha256) select tenant_id,id,'40000000-0000-4000-8000-000000226011','50000000-0000-4000-8000-000000226011','20000000-0000-4000-8000-000000226011','png',1920,1080,repeat('a',64) from public.studio_projects where name='Library 0001';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226011',true);
select is((select status from public.sync_content_library_v1 where title='Library series'),'ready','the complete current rendered series is ready under the real tenant role');
select is((select placement->>'memberCount' from public.sync_content_library_v1 where title='Library series'),'1','placement carries the complete series size for the existing atomic batch');
select is((select preview_asset_id from public.sync_content_library_v1 where title='Library series'),'20000000-0000-4000-8000-000000226011'::uuid,'preview points to the current immutable export');
reset role;
update public.studio_project_drafts set document_json='{"edited":true}',document_hash=encode(digest('{"edited":true}','sha256'),'hex') where project_id in(select id from public.studio_projects where name='Library 0001');
select is((select status from public.sync_content_library_v1 where title='Library series'),'draft','editing a draft invalidates readiness without mutating the old export');
select ok((select placement is null from public.sync_content_library_v1 where title='Library series'),'a stale historical render cannot be silently added as the edited design');
select is((select count(*)::integer from public.studio_exports where revision_id='40000000-0000-4000-8000-000000226011'),1,'the prior immutable export remains available for existing releases');
select * from finish();
rollback;
